@startuml

class Airline {
  + ID : string
}

class Flight {
  + ID : string
  + DepartureTime : datetime
  + ArrivalTime : datetime
}

class Airport {
  + ID : string
}

class Aircraft {
  + Type : string
  + IsUnderRepair : boolean
  + IsAirborne : boolean
}

class Pilot {
  + ExperienceLevel : int
}

class AircraftType {
  + Name : string
}

class PilotRoleRequirement {
  + Role : string
  + MinimumCount : int
}

class PilotRoleAssignment {
  + Role : string
}

Airline "1" -- "*" Flight
Airline "1" -- "*" Aircraft
Flight "*" -- "1" Airport : departure
Flight "*" -- "1" Airport : arrival
Flight "1" -- "1" Pilot : captain
Flight "1" -- "1" Pilot : co-pilot
Flight "*" -- "1" Aircraft
Aircraft "*" -- "1" AircraftType
AircraftType "1" -- "*" PilotRoleRequirement
Pilot "*" -- "1" PilotRoleRequirement

@enduml

